export function displayConfigValue(key: string, raw: unknown): string {
  if (raw === undefined || raw === null || raw === "") return "(not set)";
  if (isSecretKey(key)) {
    const s = String(raw);
    if (s.length <= 8) return "(set)";
    return `${s.slice(0, 4)}…${s.slice(-4)}`;
